SELECT length(CAST(COALESCE(existing_commit,'') AS BLOB)) + length(CAST(COALESCE(new_commit,'') AS BLOB)) +
      length(CAST(COALESCE(existing_reveal,'') AS BLOB)) + length(CAST(COALESCE(new_reveal,'') AS BLOB)) +
      length(CAST(COALESCE(decision,'') AS BLOB)) + length(CAST(COALESCE(cancellation,'') AS BLOB)) AS bytes FROM ${expression} WHERE ${expression}
